# decision_engine.py
# The socket Claude's scaffold calls into. Everything upstream
# of this (chain reading, dashboard, logging) was generated by
# Claude Code. This file is the one hand-written piece: it wires
# the app's state into Jev and returns a typed decision.

import os
import json
import urllib.request

JEV_ENDPOINT = "https://api.typesafe.ai/v1/systemone"
JEV_API_KEY = os.environ.get("TYPESAFE_API_KEY")


def _ask_jev(state, questions, model="jev-latest"):
    payload = {"state": state, "model": model, "questions": questions}
    body = json.dumps(payload).encode()
    req = urllib.request.Request(
        JEV_ENDPOINT,
        body,
        {
            "Authorization": f"Bearer {JEV_API_KEY}",
            "Content-Type": "application/json",
        },
    )
    with urllib.request.urlopen(req, timeout=10) as r:
        return json.load(r)["answers"]


def decide(state: dict) -> dict:
    """
    The interface Claude's scaffold expects. Takes the app's
    state dict for a token, returns a normalized decision.
    """
    questions = {
        "action": {
            "type": "choice",
            "instructions": "Should I enter a position in this token right now?",
            "criteria": {
                "buy": "Strong momentum, healthy buy pressure, acceptable risk",
                "hold": "Not enough signal to act either way",
                "skip": "Red flags outweigh any opportunity here",
            },
        },
        "risk_score": {
            "type": "score",
            "instructions": "Rate rug-pull / scam risk from 1 (safe) to 10 (extreme)",
            "levels": 10,
        },
    }

    answers = _ask_jev(state, questions)

    return {
        "action": answers["action"]["choice"],
        "confidence": answers["action"]["confidence"],
        "risk_score": answers["risk_score"]["score"],
        "risk_levels": 10,  # tells the risk gate this score is on a 1..10 scale
    }
